class FreqStack {
    unordered_map<int, int> freq;
    unordered_map<int, vector<int>> group;
    int max_freq = 0;
public:
    FreqStack() {}

    void push(int val) {
        int f = ++freq[val];
        max_freq = max(max_freq, f);
        group[f].push_back(val);
    }

    int pop() {
        int val = group[max_freq].back();
        group[max_freq].pop_back();
        freq[val]--;
        if (group[max_freq].empty()) {
            max_freq--;
        }
        return val;
    }
};

import java.util.*;

class FreqStack {
    private Map<Integer, Integer> freq;
    private Map<Integer, Deque<Integer>> group;
    private int maxFreq;

    public FreqStack() {
        freq = new HashMap<>();
        group = new HashMap<>();
        maxFreq = 0;
    }

    public void push(int val) {
        int f = freq.getOrDefault(val, 0) + 1;
        freq.put(val, f);
        if (f > maxFreq) maxFreq = f;
        group.computeIfAbsent(f, k -> new ArrayDeque<>()).push(val);
    }

    public int pop() {
        int val = group.get(maxFreq).pop();
        freq.put(val, freq.get(val) - 1);
        if (group.get(maxFreq).isEmpty()) {
            maxFreq--;
        }
        return val;
    }
}

var FreqStack = function() {
    this.freq = new Map();
    this.group = new Map();
    this.maxFreq = 0;
};

/** 
 * @param {number} val
 * @return {void}
 */
FreqStack.prototype.push = function(val) {
    const f = (this.freq.get(val) || 0) + 1;
    this.freq.set(val, f);
    if (f > this.maxFreq) this.maxFreq = f;
    if (!this.group.has(f)) this.group.set(f, []);
    this.group.get(f).push(val);
};

/**
 * @return {number}
 */
FreqStack.prototype.pop = function() {
    const bucket = this.group.get(this.maxFreq);
    const val = bucket.pop();
    this.freq.set(val, this.freq.get(val) - 1);
    if (bucket.length === 0) {
        this.maxFreq--;
    }
    return val;
};
